#!/usr/bin/env ruby
require 'json';require 'fileutils'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);dir=File.join(client,'tests/reports');schema=JSON.parse(File.read(File.join(root,'config/client-test-report-schema.json')));reports=Dir.glob(File.join(dir,'**/*')).select{|p|File.file?(p)&&File.basename(p)!='README.md'&&!p.end_with?('.metadata.json')};missing=reports.reject{|p|File.file?(p+'.metadata.json')};invalid=reports.reject do|p|begin;m=JSON.parse(File.read(p+'.metadata.json'));schema['required'].all?{|k|m.key?(k)};rescue;false;end;end;checks={allReportsHaveMetadata:missing.empty?,allMetadataComplete:invalid.empty?,reportsGeneratedOnly:File.read(File.join(client,'.gitignore')).include?('/tests/reports/')};report={schemaVersion:1,reports:reports.map{|p|p.delete_prefix(client+'/')},missingMetadata:missing.map{|p|p.delete_prefix(client+'/')},invalidMetadata:invalid.map{|p|p.delete_prefix(client+'/')},checks:checks,passed:checks.values.all?};out=File.join(root,'docs/generated/chyg04-test-reports.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "CHYG04 failed: #{checks}" unless report[:passed];puts 'CHYG04 PASS: test reports are generated-only and execution-bound'
